create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text,role text not null check(role in ('admin','editor')),created_at timestamptz default now(),updated_at timestamptz default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create table public.itineraries(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null check(slug ~ '^[a-z0-9-]+$'),short_description text default '',overview text default '',duration_days integer check(duration_days>0),duration_nights integer check(duration_nights>=0),starting_location text default '',destinations text[] default '{}',highlights text[] default '{}',accommodation text default '',meals text default '',transport text default '',included_items text[] default '{}',excluded_items text[] default '{}',packing_list text[] default '{}',important_information text default '',group_size text default '',price_from numeric check(price_from>=0),currency text default 'USD',show_price boolean default false,cover_image_url text default '',featured boolean default false,status text not null default 'draft' check(status in ('draft','published')),display_order integer default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.itinerary_days(id uuid primary key default gen_random_uuid(),itinerary_id uuid not null references public.itineraries on delete cascade,day_number integer check(day_number>0),title text not null,description text default '',meals text default '',accommodation text default '',created_at timestamptz default now(),updated_at timestamptz default now(),unique(itinerary_id,day_number));
create table public.photo_submissions(id uuid primary key default gen_random_uuid(),guest_name text not null,guest_email text not null,safari_date date,itinerary_id uuid references public.itineraries on delete set null,storage_path text unique not null,original_filename text,file_size bigint check(file_size between 1 and 10485760),mime_type text check(mime_type in ('image/jpeg','image/png','image/webp')),caption text,category text,photographer_credit text,display_credit boolean default false,consent_to_publish boolean not null check(consent_to_publish),accepted_terms boolean not null check(accepted_terms),status text not null default 'pending' check(status in ('pending','approved','rejected')),rejection_note text,reviewed_by uuid references auth.users,reviewed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.gallery_images(id uuid primary key default gen_random_uuid(),storage_path text unique not null,public_url text,title text,caption text,alt_text text not null,category text,photographer_name text,source_type text default 'company' check(source_type in ('company','guest')),submission_id uuid unique references public.photo_submissions on delete set null,status text not null default 'pending' check(status in ('pending','approved','rejected')),published boolean not null default false,featured boolean default false,display_order integer default 0,created_at timestamptz default now(),updated_at timestamptz default now(),check(not published or status='approved'));
create table public.booking_enquiries(id uuid primary key default gen_random_uuid(),full_name text not null,email text not null,phone text,country text,itinerary_id uuid references public.itineraries on delete set null,preferred_date date,flexible_dates boolean default false,adults integer check(adults between 1 and 100),children integer check(children between 0 and 100),accommodation_preference text,special_requirements text,message text,status text not null default 'new' check(status in ('new','reviewed','closed')),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.contact_enquiries(id uuid primary key default gen_random_uuid(),full_name text not null,email text not null,phone text,subject text not null,message text not null,status text not null default 'new' check(status in ('new','reviewed','closed')),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.website_settings(id uuid primary key default gen_random_uuid(),singleton boolean unique default true check(singleton),company_name text default 'The Great Nile Migration Safaris',short_description text default '',whatsapp_number text default '' check(whatsapp_number='' or whatsapp_number ~ '^[1-9][0-9]{6,14}$'),phone_number text default '',email_address text default '',office_address text default '',business_hours text default '',facebook_url text default '',instagram_url text default '',youtube_url text default '',tiktok_url text default '',seo_title text default '',seo_description text default '',updated_at timestamptz default now());
create function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text;begin foreach t in array array['profiles','itineraries','itinerary_days','photo_submissions','gallery_images','booking_enquiries','contact_enquiries','website_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('create trigger touch before update on public.%I for each row execute function public.touch_updated_at()',t);execute format('create policy admin_manage on public.%I for all to authenticated using(public.is_admin()) with check(public.is_admin())',t);end loop;end $$;
create policy own_role on public.profiles for select to authenticated using(id=auth.uid());
create policy published_safaris on public.itineraries for select to anon,authenticated using(status='published');
create policy published_days on public.itinerary_days for select to anon,authenticated using(exists(select 1 from public.itineraries where id=itinerary_id and status='published'));
create policy published_photos on public.gallery_images for select to anon,authenticated using(status='approved' and published);
create policy public_settings on public.website_settings for select to anon,authenticated using(true);
create policy send_contact on public.contact_enquiries for insert to anon,authenticated with check(status='new' and length(full_name) between 1 and 200 and length(message) between 1 and 10000 and length(email)<255 and email like '%@%.%');
create policy send_booking on public.booking_enquiries for insert to anon,authenticated with check(status='new' and adults>=1 and children>=0 and (flexible_dates or preferred_date>=current_date) and length(full_name) between 1 and 200 and length(email)<255 and email like '%@%.%');
-- Guest metadata and uploads are accepted only by the controlled Edge Function.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('guest-submissions','guest-submissions',false,10485760,array['image/jpeg','image/png','image/webp']),('safari-gallery','safari-gallery',false,10485760,array['image/jpeg','image/png','image/webp']);
create policy admin_objects on storage.objects for all to authenticated using(bucket_id in ('guest-submissions','safari-gallery') and public.is_admin()) with check(bucket_id in ('guest-submissions','safari-gallery') and public.is_admin());
create policy published_objects on storage.objects for select to anon,authenticated using(bucket_id='safari-gallery' and exists(select 1 from public.gallery_images where storage_path=name and published and status='approved'));
create index gallery_public on public.gallery_images(status,published,display_order);
create index submissions_queue on public.photo_submissions(status,created_at desc);
create index itinerary_public on public.itineraries(status,display_order);
insert into public.website_settings(company_name) values('The Great Nile Migration Safaris');
